CREATE Proc [dbo].[RptPaymentVoucher] @Type as nvarchar(50),@id as int as if @Type = 'CASH' begin Select 'CASH PAYMENT VOUCHER' as ReportType,m.VN,m.Date,m.TotalAmount,c.AccNo as PaidFromAccountNo,c.AccName as PaidFromAccountName  ,d.Amount,cc.AccNo as PaidToAccountNo,cc.AccName as PaidToAccountName,'0' as AmountInWords,d.[desc], '' as STR1,'' as STR2,'' as STR3,'' as STR4,'' as STR5, Cast(isnull(Round('0',2),0) AS DECIMAL (18,2))as dec1, Cast(isnull(Round('0',2),0) AS DECIMAL (18,2)) as dec2, Cast(isnull(Round('0',2),0) AS DECIMAL (18,2)) as dec3, Cast(isnull(Round('0',2),0) AS DECIMAL (18,2)) as dec4, Cast(isnull(Round('0',2),0) AS DECIMAL (18,2)) as dec5 from CashPaymentMaster m  inner join ChartOfaccount c on m.CAId = c.CAId inner join CashPaymentDetail d on m.CPId =d.CPId inner join ChartOfaccount cc on d.CAId = cc.CAId where m.CPId = @id and d.amount > 0  end else if @Type = 'BANK' begin Select  'BANK PAYMENT VOUCHER' as ReportType,m.VN,m.Date,m.TotalAmount,ChequeNo,ChequeDate,c.AccNo as PaidFromAccountNo ,c.AccName as PaidFromAccountName ,d.Amount,cc.AccNo as PaidToAccountNo,cc.AccName as PaidToAccountName,'0' as AmountInWords,d.[desc],'' as STR1,'' as STR2,'' as STR3,'' as STR4,'' as STR5, Cast(isnull(Round('0',2),0) AS DECIMAL (18,2)) as dec1, Cast(isnull(Round('0',2),0) AS DECIMAL (18,2)) as dec2, Cast(isnull(Round('0',2),0) AS DECIMAL (18,2)) as dec3, Cast(isnull(Round('0',2),0) AS DECIMAL (18,2)) as dec4,Cast(isnull(Round('0',2),0) AS DECIMAL (18,2)) as dec5  from BankPaymentMaster m  inner join ChartOfaccount c on m.CAId = c.CAId inner join BankPaymentDetail d on m.BPId =d.BPId inner join ChartOfaccount cc on d.CAId = cc.CAId where m.BPId = @id and d.amount > 0 end